145	  @Test
146	  public void testFinding() {
147	    CompressionCodecFactory factory =
148	      new CompressionCodecFactory(new Configuration());
149	    CompressionCodec codec = factory.getCodec(new Path("/tmp/foo.bar"));
150	    assertEquals("default factory foo codec", null, codec);
151	    codec = factory.getCodecByClassName(BarCodec.class.getCanonicalName());
152	    assertEquals("default factory foo codec", null, codec);
153	    
154	    codec = factory.getCodec(new Path("/tmp/foo.gz"));
155	    checkCodec("default factory for .gz", GzipCodec.class, codec);
156	    codec = factory.getCodecByClassName(GzipCodec.class.getCanonicalName());
157	    checkCodec("default factory for gzip codec", GzipCodec.class, codec);
158	    codec = factory.getCodecByName("gzip");
159	    checkCodec("default factory for gzip codec", GzipCodec.class, codec);
160	    codec = factory.getCodecByName("GZIP");
161	    checkCodec("default factory for gzip codec", GzipCodec.class, codec);
162	    codec = factory.getCodecByName("GZIPCodec");
163	    checkCodec("default factory for gzip codec", GzipCodec.class, codec);
164	    codec = factory.getCodecByName("gzipcodec");
165	    checkCodec("default factory for gzip codec", GzipCodec.class, codec);
166	    Class klass = factory.getCodecClassByName("gzipcodec");
167	    assertEquals(GzipCodec.class, klass);
168	
169	    codec = factory.getCodec(new Path("/tmp/foo.bz2"));
170	    checkCodec("default factory for .bz2", BZip2Codec.class, codec);
171	    codec = factory.getCodecByClassName(BZip2Codec.class.getCanonicalName());
172	    checkCodec("default factory for bzip2 codec", BZip2Codec.class, codec);
173	    codec = factory.getCodecByName("bzip2");
174	    checkCodec("default factory for bzip2 codec", BZip2Codec.class, codec);
175	    codec = factory.getCodecByName("bzip2codec");
176	    checkCodec("default factory for bzip2 codec", BZip2Codec.class, codec);
177	    codec = factory.getCodecByName("BZIP2");
178	    checkCodec("default factory for bzip2 codec", BZip2Codec.class, codec);
179	    codec = factory.getCodecByName("BZIP2CODEC");
180	    checkCodec("default factory for bzip2 codec", BZip2Codec.class, codec);
181	
182	    codec = factory.getCodecByClassName(DeflateCodec.class.getCanonicalName());
183	    checkCodec("default factory for deflate codec", DeflateCodec.class, codec);
184	    codec = factory.getCodecByName("deflate");
185	    checkCodec("default factory for deflate codec", DeflateCodec.class, codec);
186	    codec = factory.getCodecByName("deflatecodec");
187	    checkCodec("default factory for deflate codec", DeflateCodec.class, codec);
188	    codec = factory.getCodecByName("DEFLATE");
189	    checkCodec("default factory for deflate codec", DeflateCodec.class, codec);
190	    codec = factory.getCodecByName("DEFLATECODEC");
191	    checkCodec("default factory for deflate codec", DeflateCodec.class, codec);
192	
193	    factory = setClasses(new Class[0]);
194	    // gz, bz2, snappy, lz4 are picked up by service loader, but bar isn't
195	    codec = factory.getCodec(new Path("/tmp/foo.bar"));
196	    assertEquals("empty factory bar codec", null, codec);
197	    codec = factory.getCodecByClassName(BarCodec.class.getCanonicalName());
198	    assertEquals("empty factory bar codec", null, codec);
199	    
200	    codec = factory.getCodec(new Path("/tmp/foo.gz"));
201	    checkCodec("empty factory gz codec", GzipCodec.class, codec);
202	    codec = factory.getCodecByClassName(GzipCodec.class.getCanonicalName());
203	    checkCodec("empty factory gz codec", GzipCodec.class, codec);
