205	    codec = factory.getCodec(new Path("/tmp/foo.bz2"));
206	    checkCodec("empty factory for .bz2", BZip2Codec.class, codec);
207	    codec = factory.getCodecByClassName(BZip2Codec.class.getCanonicalName());
