217	    codec = factory.getCodecByClassName(Lz4Codec.class.getCanonicalName());
218	    checkCodec("empty factory lz4 codec", Lz4Codec.class, codec);
219	    
220	    factory = setClasses(new Class[]{BarCodec.class, FooCodec.class, 
221	                                     FooBarCodec.class});
222	    codec = factory.getCodec(new Path("/tmp/.foo.bar.gz"));
223	    checkCodec("full factory gz codec", GzipCodec.class, codec);
224	    codec = factory.getCodecByClassName(GzipCodec.class.getCanonicalName());
